import{_ as t,o,c as n,ag as s}from"./chunks/framework.D5hoimZQ.js";const p=JSON.parse('{"title":"🔬 科学快报 | 2026年9月5日（第 ? 期 · 事后重建版）","description":"","frontmatter":{"sidebar":true},"headers":[],"relativePath":"science-log/src/reconstructed/2026-09-05.md","filePath":"science-log/src/reconstructed/2026-09-05.md"}'),e={name:"science-log/src/reconstructed/2026-09-05.md"};function a(g,r,i,l,u,c){return o(),n("div",null,[...r[0]||(r[0]=[s('<h1 id="🔬-科学快报-2026年9月5日-第-期-·-事后重建版" tabindex="-1">🔬 科学快报 | 2026年9月5日（第 ? 期 · 事后重建版） <a class="header-anchor" href="#🔬-科学快报-2026年9月5日-第-期-·-事后重建版" aria-label="Permalink to &quot;🔬 科学快报 | 2026年9月5日（第 ? 期 · 事后重建版）&quot;">​</a></h1><blockquote><p>⚠️ <strong>事后重建版</strong>：本文件<strong>不是</strong>当日发布原文。由 2026-11-05 依 arXiv / CrossRef <strong>按发布日期回溯检索</strong>生成，选题与排序均为事后判定，<strong>不代表历史原貌</strong>。 说明：2026-09-05 为<strong>周六</strong>。CrossRef 精确当日命中：Nature（0028-0836）<strong>0 条</strong>、PNAS（0027-8424）<strong>0 条</strong>、Science 系（10.1126）仅 1 条且为<strong>新闻稿</strong>（<code>Outrage greets NIH pact…</code>，非研究论文）——即<strong>当日各大刊无研究论文上线</strong>。故科学 5 篇改从<strong>最近出版窗口 2026-08-28 ~ 2026-09-08</strong> 的 <code>published</code> 命中中选取（Nature <code>s41586-…</code> 研究论文 9 篇、Science 研究论文 20 余条），优先取<strong>距目标日最近者（9-02 / 9-03）</strong>、方法新颖且结论具体者。<strong>AI 5 篇</strong>为当日 arXiv cs.AI 提交（submittedDate <code>[202609050000 TO 202609052359]</code> 命中 91 篇，取前 30）。期号因当日原本无刊期，标为 <code>（第 ? 期 · 事后重建版）</code>。 取证：CrossRef（Nature 0028-0836 / Science 10.1126 / PNAS 0027-8424）+ arXiv 日期区间 ｜ 重建日：2026-11-05</p></blockquote><h2 id="🔬-科学前沿" tabindex="-1">🔬 科学前沿 <a class="header-anchor" href="#🔬-科学前沿" aria-label="Permalink to &quot;🔬 科学前沿&quot;">​</a></h2><h3 id="🧬-让核糖体翻译自己-rna-里的基因-把编码序列写进-16s-rrna" tabindex="-1">🧬 让核糖体翻译自己 RNA 里的基因：把编码序列写进 16S rRNA <a class="header-anchor" href="#🧬-让核糖体翻译自己-rna-里的基因-把编码序列写进-16s-rrna" aria-label="Permalink to &quot;🧬 让核糖体翻译自己 RNA 里的基因：把编码序列写进 16S rRNA&quot;">​</a></h3><p><strong>Rewiring the ribosome to translate proteins encoded in its own RNA</strong><em>Nature（2026）</em></p><p>细胞翻译依赖核糖体与 mRNA 的<strong>随机碰撞</strong>，这让&quot;把机器全部产能导向单一蛋白&quot;这件事很难优化。本文给出一个激进方案：<strong>把蛋白编码序列直接接在 16S rRNA 上</strong>，构成嵌合的&quot;信使—核糖体 RNA&quot;（mrRNA）。该杂合 RNA 能组装成小亚基、再与大亚基结合成 <strong>Ribo-M</strong>，从而<strong>翻译 mrRNA 自身编码的蛋白</strong>；用小亚基功能受损的突变或抗生素处理后翻译即消失，证明这一翻译是<strong>顺式（in cis）<strong>由组装在该嵌合 RNA 上的核糖体完成的。进一步把 mrRNA 装进&quot;亚基被拴住&quot;的核糖体得到 <strong>Ribo-TM</strong>，令编码、解码与肽合成统一在</strong>单一 RNA 支架</strong>内。除正交蛋白生产外，这也为 <strong>RNA 世界</strong>中&quot;早期翻译如何可靠运转&quot;提供了机制可行性。</p><p>📎 DOI: <a href="https://doi.org/10.1038/s41586-026-10962-1" target="_blank" rel="noreferrer">10.1038/s41586-026-10962-1</a></p><h3 id="⚛️-拆穿-平衡态双电层-模型-产氢界面下水与离子根本不同步" tabindex="-1">⚛️ 拆穿&quot;平衡态双电层&quot;模型：产氢界面下水与离子根本不同步 <a class="header-anchor" href="#⚛️-拆穿-平衡态双电层-模型-产氢界面下水与离子根本不同步" aria-label="Permalink to &quot;⚛️ 拆穿&quot;平衡态双电层&quot;模型：产氢界面下水与离子根本不同步&quot;">​</a></h3><p><strong>Probing far-from-equilibrium dynamics of electrical double layers</strong><em>Nature（2026）</em></p><p>电解固—液界面（双电层 EDL）的强局域电场支配反应动力学，但经典 EDL 模型是在<strong>平衡、非反应</strong>条件下推导的，无法描述真实电催化中的<strong>远离平衡</strong>过程。本文用化学稳定的<strong>纳米结构 Pt 薄膜电极</strong>做高灵敏、时间分辨的<strong>表面增强红外吸收光谱（SEIRAS）</strong>，在高过电位下直接观测 <strong>HER（析氢反应）<strong>时的 EDL 动态；同时用</strong>机器学习分子动力学（MLMD）<strong>捕捉纳秒尺度界面电荷涨落与溶剂动力学。两者结合揭示</strong>内层呈非线性两阶段演化</strong>并放大局域电场，时间分辨谱还发现循环电位调制下<strong>界面水的不可逆重构</strong>。核心结论：<strong>离子与界面水在远离平衡时响应不同步</strong>——为电解质设计与能量转换中的静电电位变化给出定量分子框架。</p><p>📎 DOI: <a href="https://doi.org/10.1038/s41586-026-10986-7" target="_blank" rel="noreferrer">10.1038/s41586-026-10986-7</a></p><h3 id="🧫-司美格鲁肽做成-热量限制模拟物-晚年用药延长雌鼠寿命" tabindex="-1">🧫 司美格鲁肽做成&quot;热量限制模拟物&quot;：晚年用药延长雌鼠寿命 <a class="header-anchor" href="#🧫-司美格鲁肽做成-热量限制模拟物-晚年用药延长雌鼠寿命" aria-label="Permalink to &quot;🧫 司美格鲁肽做成&quot;热量限制模拟物&quot;：晚年用药延长雌鼠寿命&quot;">​</a></h3><p><strong>Late-life semaglutide treatment slows ageing and extends lifespan in female mice</strong><em>Nature（2026）</em></p><p>GLP-1 药物除控糖控重外还显现多种&quot;多效性&quot;获益，但其底层机制长期不明。本文给 <strong>20 月龄雌性 C57BL/6 小鼠</strong>连续 <strong>3 个月</strong>司美格鲁肽，结果<strong>改善生理功能、削弱多项衰老标志、调控营养感受器与保守的衰老基因调节因子</strong>；<strong>继续给药可延长寿命</strong>。这些效应与<strong>热量限制</strong>的关键特征平行。在与配对的<strong>热量限制</strong>做直接对照的纵向研究中，司美格鲁肽<strong>既保住了基线功能、复现了热量限制的诸多功能获益</strong>，又在<strong>探索驱动力、空间记忆与血糖控制</strong>上<strong>超过基线</strong>且轨迹优于热量限制。结论：<strong>晚年启动的 GLP-1R 激活能延缓雌鼠衰老并延长寿命</strong>，支持其作为&quot;热量限制模拟物&quot;的定位，并为解释其广谱获益给出机制框架——且提示存在<strong>超出单纯少吃</strong>的效应。</p><p>📎 DOI: <a href="https://doi.org/10.1038/s41586-026-10940-7" target="_blank" rel="noreferrer">10.1038/s41586-026-10940-7</a></p><h3 id="🧠-裸盖菇素两剂-预防-化疗神经痛-靠保住轴突线粒体运输" tabindex="-1">🧠 裸盖菇素两剂&quot;预防&quot;化疗神经痛：靠保住轴突线粒体运输 <a class="header-anchor" href="#🧠-裸盖菇素两剂-预防-化疗神经痛-靠保住轴突线粒体运输" aria-label="Permalink to &quot;🧠 裸盖菇素两剂&quot;预防&quot;化疗神经痛：靠保住轴突线粒体运输&quot;">​</a></h3><p><strong>Psilocybin prevents chemotherapy-induced peripheral neuropathy through mitochondrial trafficking preservation</strong><em>Science（2026）</em></p><p>化疗致周围神经病变（CIPN）影响数百万人、常不可逆且无成熟疗法。本文报告：<strong>化疗前仅两剂裸盖菇素</strong>即可在<strong>铂类与紫杉类</strong>模型中<strong>持久预防 CIPN 发作</strong>（含多轮重复化疗），且<strong>不削弱抗肿瘤疗效</strong>。外周层面，它通过<strong>轴突线粒体运输与分布</strong>的维持，保住<strong>触觉敏感性与表皮内神经纤维末梢</strong>，机制涉及 <strong>TrkB–Akt–PAK5–MAP2–KIF5B 通路</strong>以及把<strong>被 syntaphilin 锚定的线粒体重新动员</strong>起来。中枢层面，它让<strong>内侧前额叶皮层突触活动</strong>恢复常态，并使<strong>皮层 α、β 脑电功率</strong>正常化。作者把这一&quot;稳定外周轴突能量平衡&quot;的机制确立为一种<strong>神经保护新范式</strong>。</p><p>📎 DOI: <a href="https://doi.org/10.1126/science.aec6116" target="_blank" rel="noreferrer">10.1126/science.aec6116</a></p><h3 id="🦠-肿瘤用抗氧化酶-抽干-t-细胞的活性氧-从而逃避免疫" tabindex="-1">🦠 肿瘤用抗氧化酶&quot;抽干&quot;T 细胞的活性氧，从而逃避免疫 <a class="header-anchor" href="#🦠-肿瘤用抗氧化酶-抽干-t-细胞的活性氧-从而逃避免疫" aria-label="Permalink to &quot;🦠 肿瘤用抗氧化酶&quot;抽干&quot;T 细胞的活性氧，从而逃避免疫&quot;">​</a></h3><p><strong>Tumor-derived antioxidants suppress immunity by depriving T cells of reactive oxygen species</strong><em>Science（2026）</em></p><p>活性氧（ROS）在肿瘤中促基因组不稳定与致癌信号，但抗氧化疗法要么无效要么加重病情——本文给出一个反直觉解释：<strong>T 细胞的信号转导反而依赖 ROS</strong>。研究显示肿瘤会<strong>向微环境释放抗氧化酶</strong>来压制 T 细胞抗肿瘤免疫：肿瘤<strong>间质液具强抗氧化活性</strong>，且富集抗氧化酶 <strong>peroxiredoxin 1（PRDX1）</strong>；<strong>胞外 PRDX1 剥夺 T 细胞的 ROS</strong>，从而<strong>阻止那些对 TCR 驱动的激酶信号与效应功能必需的磷酸酶被氧化失活</strong>——即 ROS 本是解除磷酸酶&quot;刹车&quot;的信号，被抽走后刹车踩死。<strong>Prdx1 在免疫编辑中被上调</strong>，而<strong>肿瘤内丢失 PRDX1 可增强抗肿瘤免疫</strong>，把 PRDX1 指认为一个可干预靶点。</p><p>📎 DOI: <a href="https://doi.org/10.1126/science.adz8203" target="_blank" rel="noreferrer">10.1126/science.adz8203</a></p><h2 id="🤖-ai-前沿" tabindex="-1">🤖 AI 前沿 <a class="header-anchor" href="#🤖-ai-前沿" aria-label="Permalink to &quot;🤖 AI 前沿&quot;">​</a></h2><h3 id="🌬️-只用天气预报预测风机功率-数据量与预处理的系统研究" tabindex="-1">🌬️ 只用天气预报预测风机功率：数据量与预处理的系统研究 <a class="header-anchor" href="#🌬️-只用天气预报预测风机功率-数据量与预处理的系统研究" aria-label="Permalink to &quot;🌬️ 只用天气预报预测风机功率：数据量与预处理的系统研究&quot;">​</a></h3><p><strong>Predicting Wind Turbine Power Using Machine Learning and Weather Forecasts</strong><em>arXiv:2609.06194（2026）</em></p><p>海上风机的维护会因强制停机而降低效率，准确的<strong>功率预测</strong>能识别出适合安排维护的低功率时段。但<strong>数据量、特征选择与预处理</strong>对预测模型性能的影响此前未被系统研究，且现有模型在<strong>不同风机间迁移性差</strong>。本工作以<strong>只用气象条件</strong>（以提升适用性）为前提，建立<strong>线性回归基线</strong>并与更复杂的<strong>人工神经网络</strong>对比，比较了多种数据预处理技术，并分别在<strong>一个月与一年</strong>的数据上训练以考察数据量的作用。属于&quot;把预测模型从单一机组推向可迁移&quot;的工程化路线，对<strong>风电场运维调度</strong>有直接价值。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2609.06194" target="_blank" rel="noreferrer">2609.06194</a></p><h3 id="🧭-llm-激活空间的-价值几何-人类价值理论能否被转向向量复现" tabindex="-1">🧭 LLM 激活空间的&quot;价值几何&quot;：人类价值理论能否被转向向量复现 <a class="header-anchor" href="#🧭-llm-激活空间的-价值几何-人类价值理论能否被转向向量复现" aria-label="Permalink to &quot;🧭 LLM 激活空间的&quot;价值几何&quot;：人类价值理论能否被转向向量复现&quot;">​</a></h3><p><strong>Steering Geometry: Validating Human Value Geometry in LLM Steering Space</strong><em>arXiv:2609.06289（2026）</em></p><p><strong>激活转向（activation steering）<strong>是推理时控制 LLM 行为的轻量替代方案，但以往多在</strong>孤立行为</strong>上验证，尚不清楚转向向量究竟编码了<strong>连贯的语义结构</strong>，还是只抓住了<strong>行为特异的捷径</strong>。本文以 <strong>Schwartz 基本人类价值理论</strong>为细粒度框架，构建 <strong>26K 样本、覆盖 20 种人类价值</strong>的基准，对分布驱动方法（CAA、SphericalSteer、ODESteer）与行为中心方法（COLD-Steer、BiPO）在<strong>不同模型族与规模</strong>上进行系统分析，检验转向向量的<strong>潜在几何</strong>是否反映理论指定的结构。这是把&quot;对齐可解释性&quot;从单点行为推进到<strong>理论化几何检验</strong>的一步。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2609.06289" target="_blank" rel="noreferrer">2609.06289</a></p><h3 id="🔢-真正的-1-比特量化-消除-llm-二值化-ptq-的隐性开销" tabindex="-1">🔢 真正的 1 比特量化：消除 LLM 二值化 PTQ 的隐性开销 <a class="header-anchor" href="#🔢-真正的-1-比特量化-消除-llm-二值化-ptq-的隐性开销" aria-label="Permalink to &quot;🔢 真正的 1 比特量化：消除 LLM 二值化 PTQ 的隐性开销&quot;">​</a></h3><p><strong>All for 1-Bit: Towards Genuine 1-Bit Post-Training Quantization for LLMs</strong><em>arXiv:2609.06161（2026）</em></p><p>LLM 的存储与显存带宽需求阻碍部署，<strong>权值二值化</strong>是有前途的解法，但现有基于二值化的<strong>训练后量化（PTQ）<strong>方法常因</strong>隐性开销</strong>而<strong>远超名义 1 比特存储目标</strong>。本文提出 <strong>AF1</strong> 框架，含两个互补组件：(1) <strong>Null-space-Aware Binary Factorization（NABF）</strong>——通过 Hessian 感知的代理重参数化、零空间感知的二值分解与&quot;仅缩放&quot;的全局重建改进二值重构；(2) <strong>Hierarchical Shapley Allocation（HiSA）</strong>——用<strong>分层 Shapley 敏感度</strong>分配结构容量。二者合起来在<strong>严格 1.0 BPW 预算</strong>下保持模型精度，把&quot;名义 1 比特&quot;落成&quot;<strong>名副其实 1 比特</strong>&quot;。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2609.06161" target="_blank" rel="noreferrer">2609.06161</a></p><h3 id="📰-佐证幻觉-更多新闻反而让-llm-预测更不准" tabindex="-1">📰 佐证幻觉：更多新闻反而让 LLM 预测更不准 <a class="header-anchor" href="#📰-佐证幻觉-更多新闻反而让-llm-预测更不准" aria-label="Permalink to &quot;📰 佐证幻觉：更多新闻反而让 LLM 预测更不准&quot;">​</a></h3><p><strong>The Corroboration Illusion: When More News Makes LLM Forecasts Less True</strong><em>arXiv:2609.22246（2026）</em></p><p>LLM 越来越多地通过<strong>检索并推理新闻</strong>来预测现实事件，而这种对<strong>开放可爬取新闻语料</strong>的依赖创造了新的攻击面：攻击者<strong>无需接触检索器、模型或用户查询</strong>，仅靠<strong>发布文章</strong>就能系统性移动预测器的输出概率。作者把这一威胁形式化为<strong>面向概率预测器的新闻语料投毒</strong>——区别于以往针对<strong>事实答案或观点极性</strong>的 RAG 投毒，它瞄准的是<strong>校准概率</strong>。在 <strong>500 道已揭晓的 ForecastBench 题目</strong>上，对抗 <strong>1740 万篇</strong> Common Crawl News 语料（严格爬取日期截断），针对三个基于开源 <strong>7–8B</strong> 模型的检索增强预测器评估：<strong>每题仅一篇 LLM 撰写的文章即可使 56% 的预测跨越 0.5 边界</strong>。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2609.22246" target="_blank" rel="noreferrer">2609.22246</a></p><h3 id="🧮-带证明的代数量几何检索-用层论给-rag-的结构-定性" tabindex="-1">🧮 带证明的代数量几何检索：用层论给 RAG 的结构&quot;定性&quot; <a class="header-anchor" href="#🧮-带证明的代数量几何检索-用层论给-rag-的结构-定性" aria-label="Permalink to &quot;🧮 带证明的代数量几何检索：用层论给 RAG 的结构&quot;定性&quot;&quot;">​</a></h3><p><strong>PAGR: Proof-Carrying Algebraic-Geometric Retrieval: A Quiver-, Provenance-, and Sheaf-Theoretic Framework for Grounded LLM Retrieval</strong><em>arXiv:2609.06127（2026）</em></p><p>RAG 常被表述为统计信息检索问题；图结构变体虽加入关系结构，但其<strong>数学地位</strong>往往未被明确——&quot;哪些陈述被认证为知识&quot;&quot;哪些潜在表示利于检索&quot;&quot;哪些多跳组合语义上可容许&quot;三个问题常被混为一谈。<strong>PAGR</strong> 把三者<strong>在数学上分离</strong>：符号层是由<strong>类型化 quiver、路径方程与正 Horn 包含</strong>生成的<strong>多类关系理论</strong>；<strong>quiver 表示</strong>给实体类型赋内积空间、给关系赋线性算子；<strong>胞腔层（cellular sheaf）<strong>度量</strong>局部—全局一致性</strong>；**半环溯源（semiring provenance）**记录推导过程。为&quot;有据可依的检索&quot;提供了一套可携带证明的形式化骨架。</p><p>📎 arXiv: <a href="https://arxiv.org/abs/2609.06127" target="_blank" rel="noreferrer">2609.06127</a></p><blockquote><p>📅 日期：2026-09-05 ｜ ⚠️ 事后重建版 ｜ 📂 科学前沿 5 篇 | 🤖 AI前沿 5 篇</p></blockquote>',45)])])}const d=t(e,[["render",a]]);export{p as __pageData,d as default};
